-- =====================================================================
-- 02_seed.sql : MADE-UP sample data. Generated by scripts/generate-seed.mjs
-- Do not edit by hand; change the script and run  npm run seed:generate
--
-- Dates are written as  current_date - N  so the data always looks recent.
-- "overriding system value" lets us choose the ID numbers ourselves, so
-- the order lines can point at the right orders.
-- =====================================================================

begin;
truncate receiving.receipt_lines, receiving.receipts, receiving.po_lines,
         receiving.purchase_orders, receiving.products, receiving.suppliers;







-- Move each ID counter past the rows we inserted, so new rows get new IDs.
select setval(pg_get_serial_sequence('receiving.suppliers', 'supplier_id'), (select coalesce(max(supplier_id), 0) + 1 from receiving.suppliers), false);
select setval(pg_get_serial_sequence('receiving.products', 'product_id'), (select coalesce(max(product_id), 0) + 1 from receiving.products), false);
select setval(pg_get_serial_sequence('receiving.purchase_orders', 'po_id'), (select coalesce(max(po_id), 0) + 1 from receiving.purchase_orders), false);
select setval(pg_get_serial_sequence('receiving.po_lines', 'po_line_id'), (select coalesce(max(po_line_id), 0) + 1 from receiving.po_lines), false);
select setval(pg_get_serial_sequence('receiving.receipts', 'receipt_id'), (select coalesce(max(receipt_id), 0) + 1 from receiving.receipts), false);
select setval(pg_get_serial_sequence('receiving.receipt_lines', 'receipt_line_id'), (select coalesce(max(receipt_line_id), 0) + 1 from receiving.receipt_lines), false);

commit;
